func tl0(a *tslabs, v any) []types.Expr {
	a.spend()
	if v == nil {
		return nil
	}
	n, _ := v.(*rt.TSeq)
	if n == nil {
		return []types.Expr{}
	}
	out := rt.AllocSlice(&a.tl0Chunk, len(n.Kids))
	for i, c := range n.Kids {
		a.spend()
		out[i] = rt.TAs[types.Expr](rt.TPubIn(types.SXIRHooks, a, c))
	}
	return out
}

